constraints:
1 ≤ N*|sum of array elements| ≤ 10^{6}
0 < arr[i] <= 10^{5}

expected time complexity: O(N*|sum of array elements|)
expected auxiliary space: O(N*|sum of array elements|)

standard_solution_code:
class Solution:

	def minDifference(self, arr, n):
		s = sum(arr)
		dp = [[False for j in range(s + 1)] for i in range(n)]
		for i in range(n):
			dp[i][0] = True
		dp[0][arr[0]] = True
		for i in range(1, n):
			for j in range(1, s + 1):
				not_take = dp[i - 1][j]
				take = False
				if arr[i] <= j:
					take = dp[i - 1][j - arr[i]]
				dp[i][j] = not_take | take
		t = []
		mini = 1000000000.0
		for i in range(s + 1):
			if dp[n - 1][i] == True:
				t.append(i)
		for i in range(len(t)):
			mini = min(mini, abs(s - 2 * t[i]))
		return mini
